/* Casambi BT Card v0.1.8 */
const CARD_VERSION='0.2.0';
const CARD_TAG='casambi-bt-card';
const EDITOR_TAG='casambi-bt-card-editor';
const SOURCES={raw_network:'Casambi BT / RAW Network',android_bridge:'Android Casambi Bridge',jungle:'Casambi Jungle / Direct',name_only:'Name/Network Match'};
const PRESETS=['djungle','lcars','lcars-bars','lcars-command','lcars-classic','lcars-terminal','casambi-native','casambi-neon','cyberpunk-blue','cyberpunk-purple','space-opera','mushroom-soft','mushroom-dark','bubble-compact','bubble-glass','minimal'];
const LAYOUTS=['default','compact','wide','scenes-first','lights-first'];
const DEFAULT_CFG={title:'Casambi',preset:'djungle',layout:'default',network_config_entity:'',discovery:{strict_casambi_matching:true,enabled_sources:['raw_network'],prefer_available:true,hide_unavailable_duplicates:true,show_rejected_candidates:true},controls:{brightness:true,color_temp:'auto'},show_header:true,show_stats:true,show_scenes:true,show_lights:true,show_footer:true,lights:[],scenes:[]};
const name=s=>s?.attributes?.friendly_name||s?.entity_id||'';
const dom=e=>(e||'').split('.')[0];
const unavailable=s=>!s||['unavailable','unknown'].includes(String(s.state));
const isOn=s=>['on','online','connected','true'].includes(String(s?.state||'').toLowerCase());
const list=v=>!v?[]:Array.isArray(v)?v.filter(Boolean):String(v).split(/[\n,]/).map(x=>x.trim()).filter(Boolean);
