function sourceAllowed(c,x){let e=enabled(c);if(e.includes('all'))return true;if(x.source==='name_only')return cfg(c).discovery.strict_casambi_matching===false&&e.includes('name_only');return e.includes(x.source)}
function rawData(h,c){c=cfg(c);let ent=c.network_config_entity?h.states[c.network_config_entity]:null;let states=ent?[ent]:Object.values(h.states).filter(s=>dom(s.entity_id)==='sensor'&&s.attributes?.raw_network_data?.network);for(const s of states){if(s?.attributes?.raw_network_data?.network)return{raw:s.attributes.raw_network_data,entity:s.entity_id}}return{} }
function sourceOf(s){let id=(s?.entity_id||'').toLowerCase(),fn=name(s).toLowerCase();if(id.includes('android_casambi_bridge'))return'android_bridge';if(id.includes('casambi_jungle')||id.includes('jungle'))return'jungle';if(id.includes('hue_')||fn.includes('hue ')||fn.includes(' philips hue'))return'hue';if(id.includes('shelly'))return'shelly';return'raw_network'}
function targets(h,c,type){let {raw}=rawData(h,c),net=cfg(c).network_name||raw?.network?.name||'';if(!raw?.network)return{targets:[],net};return{targets:(type==='light'?raw.network.units||[]:raw.network.scenes||[]).map(x=>x.name).filter(Boolean),net}}
function scoreEntity(s,target,net,type){let id=s.entity_id.toLowerCase(),fn=name(s),ts=slug(target),ns=slug(net),sc=0;if(fn===target)sc+=110;if(fn.toLowerCase()===String(target).toLowerCase())sc+=100;if(ns&&id.includes(ns))sc+=25;if(ts&&id.includes(ts))sc+=45;if(type==='scene'&&ns&&ts&&id===`scene.${ns}_${ts}`)sc+=180;if(!unavailable(s))sc+=30;if(sourceOf(s)!=='raw_network')sc-=60;return sc}
function candidates(h,c,type){c=cfg(c);let strict=c.discovery.strict_casambi_matching!==false,domain=type==='light'?'light':'scene',all=Object.values(h.states).filter(s=>dom(s.entity_id)===domain),{targets:tg,net}=targets(h,c,type),m=new Map();for(const t of tg){for(const s of all){let sc=scoreEntity(s,t,net,type);if(sc>=(type==='scene'?90:70)){m.set(s.entity_id,{entity_id:s.entity_id,name:name(s),state:s.state,score:sc,source:sourceOf(s),raw_match:true,available:!unavailable(s)})}}}if(!strict){for(const s of all){let id=s.entity_id.toLowerCase(),fn=name(s).toLowerCase(),ns=slug(net);if(!m.has(s.entity_id)&&(id.includes('casambi')||fn.includes('casambi')||(ns&&id.includes(ns)))){let src=sourceOf(s);m.set(s.entity_id,{entity_id:s.entity_id,name:name(s),state:s.state,score:55+(unavailable(s)?0:20),source:src==='raw_network'?'name_only':src,raw_match:false,available:!unavailable(s)})}}}return[...m.values()].sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name))}
function allowedManual(h,c,type,e){if(!h.states[e])return false;if(cfg(c).discovery.strict_casambi_matching===false&&enabled(c).includes('all'))return true;return candidates(h,c,type).some(x=>x.entity_id===e&&sourceAllowed(c,x))}
