function statusEntity(h,c){c=cfg(c);if(c.status_entity&&h.states[c.status_entity])return c.status_entity;let {raw}=rawData(h,c),ns=slug(c.network_name||raw?.network?.name||c.title||'');let best,b=-1;Object.values(h.states).filter(s=>dom(s.entity_id)==='binary_sensor').forEach(s=>{let sc=0,id=s.entity_id.toLowerCase();if(ns&&id===`binary_sensor.${ns}_status`)sc+=200;if(name(s).toLowerCase().includes('status'))sc+=25;if(sc>b){b=sc;best=s}});return b>=80?best.entity_id:undefined}
